//! 全量优化保守性：跨页、晚失败回滚、普通/临时触发器和立即自引用外键。
use super::*;
use sqlx::sqlite::{SqliteConnectOptions,SqlitePoolOptions};
struct Directory(std::path::PathBuf);
impl Drop for Directory{fn drop(&mut self){let _=std::fs::remove_dir_all(&self.0);}}
async fn fixtures()->(Directory,sqlx::SqlitePool,sqlx::SqlitePool){let dir=Directory(std::env::temp_dir().join(format!("navkit-sync-full-regression-{}",uuid::Uuid::new_v4())));std::fs::create_dir(&dir.0).unwrap();let mut pools=Vec::new();for file in ["source.sqlite","target.sqlite"]{pools.push(SqlitePoolOptions::new().max_connections(1).connect_with(SqliteConnectOptions::new().filename(dir.0.join(file)).create_if_missing(true).foreign_keys(true)).await.unwrap());}(dir,pools.remove(0),pools.remove(0))}
fn options()->SyncOptions{SyncOptions{task_id:None,source_connection:"source".into(),source_schema:"main".into(),source_table:"items".into(),target_connection:"target".into(),target_schema:"main".into(),target_table:"items".into(),mode:"data".into(),write_mode:"replace".into(),sync_mode:"full".into(),incremental_update:false,create_target:false,columns:vec![],key_columns:vec![],delete_missing:false,where_clause:None}}
async fn run(source:&sqlx::SqlitePool,target:&sqlx::SqlitePool,options:&SyncOptions)->Result<SyncReport>{let kind=DbKind::of("sqlite");synchronize(&Db::Sqlite(source.clone()),&kind,&Db::Sqlite(target.clone()),&kind,options).await}
#[tokio::test]
async fn full_batches_preserve_cross_page_rows_nuls_blobs_and_target_mapping(){let(_dir,source,target)=fixtures().await;sqlx::raw_sql("CREATE TABLE items(id INTEGER PRIMARY KEY,v TEXT,b BLOB);WITH RECURSIVE n(x) AS(VALUES(1) UNION ALL SELECT x+1 FROM n WHERE x<2501) INSERT INTO items SELECT x,'quote''nul'||char(0)||'尾',X'00FF80' FROM n").execute(&source).await.unwrap();sqlx::raw_sql("CREATE TABLE items(b BLOB,k INTEGER PRIMARY KEY,note TEXT)").execute(&target).await.unwrap();let mut opts=options();opts.columns=vec![SyncColumnMapping{source:"b".into(),target:"b".into(),target_type:None},SyncColumnMapping{source:"id".into(),target:"k".into(),target_type:None},SyncColumnMapping{source:"v".into(),target:"note".into(),target_type:None}];assert_eq!(run(&source,&target,&opts).await.unwrap().rows,2501);let row=sqlx::query("SELECT COUNT(*) AS n,SUM(k) AS total,SUM(length(b)) AS blobs FROM items").fetch_one(&target).await.unwrap();assert_eq!(row.get::<i64,_>("n"),2501);assert_eq!(row.get::<i64,_>("total"),2501*2502/2);assert_eq!(row.get::<i64,_>("blobs"),2501*3);let value:String=sqlx::query_scalar("SELECT note FROM items WHERE k=2501").fetch_one(&target).await.unwrap();assert_eq!(value,"quote'nul\0尾");source.close().await;target.close().await;}
#[tokio::test]
async fn full_late_batch_constraint_error_rolls_back_replace_and_prior_batches(){let(_dir,source,target)=fixtures().await;sqlx::raw_sql("CREATE TABLE items(id INTEGER PRIMARY KEY,v TEXT);WITH RECURSIVE n(x) AS(VALUES(1) UNION ALL SELECT x+1 FROM n WHERE x<2501) INSERT INTO items SELECT x,CASE WHEN x=2501 THEN 'bad' ELSE 'good' END FROM n").execute(&source).await.unwrap();sqlx::raw_sql("CREATE TABLE items(id INTEGER PRIMARY KEY,v TEXT CHECK(v<>'bad'));INSERT INTO items VALUES(99,'owned')").execute(&target).await.unwrap();assert!(run(&source,&target,&options()).await.is_err());let rows=sqlx::query("SELECT id,v FROM items").fetch_all(&target).await.unwrap();assert_eq!(rows.len(),1);assert_eq!(rows[0].get::<i64,_>("id"),99);assert_eq!(rows[0].get::<String,_>("v"),"owned");source.close().await;target.close().await;}
#[tokio::test]
async fn full_main_and_temp_triggers_keep_original_single_statement_changes_semantics(){for temporary in [false,true]{let(_dir,source,target)=fixtures().await;sqlx::raw_sql("CREATE TABLE items(id INTEGER PRIMARY KEY);WITH RECURSIVE n(x) AS(VALUES(1) UNION ALL SELECT x+1 FROM n WHERE x<600) INSERT INTO items SELECT x FROM n").execute(&source).await.unwrap();sqlx::raw_sql("CREATE TABLE items(id INTEGER PRIMARY KEY);INSERT INTO items VALUES(999);CREATE TABLE audit(previous_changes INTEGER)").execute(&target).await.unwrap();let trigger=format!("CREATE {}TRIGGER record_changes AFTER INSERT ON main.items BEGIN INSERT INTO audit VALUES(changes());END",if temporary{"TEMP "}else{""});sqlx::raw_sql(&trigger).execute(&target).await.unwrap();assert_eq!(run(&source,&target,&options()).await.unwrap().rows,600);let bad:i64=sqlx::query_scalar("SELECT COUNT(*) FROM audit WHERE previous_changes<>1").fetch_one(&target).await.unwrap();assert_eq!(bad,0,"带触发器不可把每条INSERT合并");let count:i64=sqlx::query_scalar("SELECT COUNT(*) FROM audit").fetch_one(&target).await.unwrap();assert_eq!(count,600);source.close().await;target.close().await;}}
#[tokio::test]
async fn full_immediate_self_foreign_key_keeps_original_row_order_failure(){let(_dir,source,target)=fixtures().await;sqlx::raw_sql("CREATE TABLE items(id INTEGER PRIMARY KEY,parent INTEGER);INSERT INTO items VALUES(1,2),(2,NULL)").execute(&source).await.unwrap();sqlx::raw_sql("CREATE TABLE items(id INTEGER PRIMARY KEY,parent INTEGER REFERENCES items(id));INSERT INTO items VALUES(99,NULL)").execute(&target).await.unwrap();assert!(run(&source,&target,&options()).await.is_err(),"自引用立即外键必须保持逐行顺序失败，不能批语句延迟检查");assert_eq!(sqlx::query_scalar::<_,i64>("SELECT id FROM items").fetch_one(&target).await.unwrap(),99);source.close().await;target.close().await;}
#[test]
fn batch_sql_limits_rows_and_bytes_and_single_row_is_never_truncated(){let spec=InsertSpec{cols:vec![("v".into(),"v".into(),"TEXT".into(),"TEXT".into())],target_names:"v".into(),full:"items".into(),schema:"main".into(),table:"items".into()};let names=vec!["v".into()];let small=vec![vec![Some("x".into())];600];let batched=spec.statements(&DbKind::of("sqlite"),&names,None,&small,true).unwrap();assert_eq!(batched.len(),3);let large=vec![vec![Some("x".repeat(600_000))];3];let batched=spec.statements(&DbKind::of("sqlite"),&names,None,&large,true).unwrap();assert_eq!(batched.len(),3);assert!(batched.iter().all(|(sql,_)|sql.len()<1024*1024));let huge=vec![vec![Some("x".repeat(1024*1024+1))]];assert!(spec.statements(&DbKind::of("sqlite"),&names,None,&huge,true).unwrap()[0].0.len()>1024*1024);}
